WatchFace({
  initView() {
    // the picked variant survives a restart (when the watch offers storage)
    let variantIdx = 0
    try { if (typeof hmFS !== 'undefined') variantIdx = Number(hmFS.SysProGetInt('dialcraft_variant')) || 0 } catch (e) {}

    // Background (FILL_RECT)
    ui.createWidget(ui.widget.FILL_RECT, {
      x: px(0),
      y: px(0),
      w: px(390),
      h: px(450),
      color: 0x000000,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Scene (IMG)
    const variants_0 = [A('scene/night.png'), A('scene/dawn.png'), A('scene/day.png'), A('scene/golden.png'), A('scene/sunset.png'), A('scene/dusk.png')]
    const hours_0 = [22,4.5,7,16.5,18.5,20]
    const tod_0 = () => { const t = new Time(); const h = t.getHours() + t.getMinutes() / 60; let b = -1, mx = 0; for (let i = 0; i < hours_0.length; i++) { if (hours_0[i] > hours_0[mx]) mx = i; if (hours_0[i] <= h && (b < 0 || hours_0[i] > hours_0[b])) b = i } return b < 0 ? mx : b }
    const variant_0 = ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(0),
      src: variants_0[tod_0()],
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Hour (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(32),
      hour_startY: px(6),
      hour_zero: 1,
      hour_space: px(-24),
      hour_align: ui.align.LEFT,
      hour_array: img_Hour_q5ys,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Colon (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(164),
      y: px(14),
      src: A('symbol_u003a.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Minute (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(192),
      minute_startY: px(6),
      minute_zero: 1,
      minute_space: px(-24),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_gqb4,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Weekday (IMG_WEEK)
    ui.createWidget(ui.widget.IMG_WEEK, {
      x: px(68),
      y: px(108),
      week_en: img_Weekday_a1q5,
      week_sc: img_Weekday_a1q5,
      week_tc: img_Weekday_a1q5,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Day (IMG_DATE)
    ui.createWidget(ui.widget.IMG_DATE, {
      day_startX: px(148),
      day_startY: px(108),
      day_zero: 0,
      day_space: px(-24),
      day_align: ui.align.LEFT,
      day_follow: 0,
      day_en_array: img_Day_ieuq,
      day_sc_array: img_Day_ieuq,
      day_tc_array: img_Day_ieuq,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Battery (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(202),
      y: px(108),
      type: ui.data_type.BATTERY,
      font_array: img_Battery_64e6,
      h_space: px(-22),
      align_h: ui.align.LEFT,
      unit_en: A('percent.png'),
      unit_sc: A('percent.png'),
      unit_tc: A('percent.png'),
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Steps (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(18),
      y: px(386),
      type: ui.data_type.STEP,
      font_array: img_Steps_jpjk,
      h_space: px(-22),
      align_h: ui.align.LEFT,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Hour Aod (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(70),
      hour_startY: px(120),
      hour_zero: 1,
      hour_space: px(0),
      hour_align: ui.align.LEFT,
      hour_array: img_Hour_Aod_g4ov,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Minute Aod (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(70),
      minute_startY: px(260),
      minute_zero: 1,
      minute_space: px(0),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_Aod_g2sx,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Chimney smoke (IMG_ANIM)
    ui.createWidget(ui.widget.IMG_ANIM, {
      x: px(277),
      y: px(126),
      anim_path: 'images/anim',
      anim_prefix: 'smoke',
      anim_ext: 'png',
      anim_fps: 8,
      anim_size: 24,
      repeat_count: 0,
      step: 1,
      anim_status: ui.anim_status.START,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // a Tap zone set to "Cycle variants" calls this
    const variantNames = ["Night","Dawn","Day","Golden hour","Sunset","Dusk"]
    const cycleVariants = () => {
      variantIdx = (variantIdx + 1) % Math.max(variants_0.length)
      try { if (typeof hmFS !== 'undefined') hmFS.SysProSetInt('dialcraft_variant', variantIdx) } catch (e) {}
      try { if (variantNames[variantIdx] && typeof hmUI !== 'undefined') hmUI.showToast({ text: variantNames[variantIdx] }) } catch (e) {}
    }
    // time-of-day variants follow the clock
    const updateTod = () => {
      variant_0.setProperty(ui.prop.SRC, variants_0[tod_0()])
    }
    const todClock = new Time()
    todClock.onPerMinute(updateTod)
    ui.createWidget(ui.widget.WIDGET_DELEGATE, { resume_call: updateTod })
  },

  build() {
    this.initView()
  },
})
